const results = [];

for (const item of $input.all()) {
  const data = item.json.body;

  // --- Extract values ---
  const budgetMin = Number(data.budget_min || 0);
  const experience = data.experience_level || "";        // "First purchase", "2–5 purchases", "5+ purchases"
  const timeline = data.timeline_to_buy || "";           // "0–3 months", "3–6 months", "6–12 months", "12+ months"
  const financing = data.financing_status || "";         // "Cash", "Pre-approved mortgage", "Not yet / Exploring"
  const propertyType = data.property_type || "";         // "Single-family", "Multi-family", "Condo", "Townhouse"

  // --- Calculate Lead Score ---
  let score = 0;
  if (budgetMin >= 200000) score += 30;

  if (experience === "5+ purchases") score += 20;
  else if (experience === "2–5 purchases") score += 10;

  if (timeline === "0–3 months") score += 30;
  else if (timeline === "3–6 months") score += 20;
  else if (timeline === "6–12 months") score += 10;

  if (["Cash", "Pre-approved mortgage"].includes(financing)) score += 20;

  // --- Determine Stage ---
  let stage = "Nurture";
  if (score >= 70) stage = "Qualified – Hot";
  else if (score >= 40) stage = "Qualified – Warm";

  // --- Build Tags ---
  const tags = ["source_chatwindow", "intent_buy_to_rent"];

  // Financing tags
  if (financing === "Cash") tags.push("financing_cash");
  else if (financing === "Pre-approved mortgage") tags.push("financing_preapproved");
  else if (financing === "Not yet / Exploring") tags.push("financing_exploring");

  // Timeline tags
  if (timeline === "0–3 months") tags.push("tl_0_3m");
  else if (timeline === "3–6 months") tags.push("tl_3_6m");
  else if (timeline === "6–12 months") tags.push("tl_6_12m");
  else if (timeline === "12+ months") tags.push("tl_12m_plus");

  // Experience tags
  if (experience === "First purchase") tags.push("xp_first");
  else if (experience === "2–5 purchases") tags.push("xp_2_5");
  else if (experience === "5+ purchases") tags.push("xp_5_plus");

  // Property type tags
  if (propertyType === "Single-family") tags.push("pt_sfh");
  else if (propertyType === "Multi-family") tags.push("pt_mfh");
  else if (propertyType === "Condo") tags.push("pt_condo");
  else if (propertyType === "Townhouse") tags.push("pt_townhouse");

  // Score bands
  if (stage === "Qualified – Hot") tags.push("score_hot");
  else if (stage === "Qualified – Warm") tags.push("score_warm");
  else tags.push("score_nurture");

  // --- Save computed values ---
  item.json.lead_score = score;
  item.json.stage = stage;
  item.json.tags = tags;

  results.push(item);
}

return results;

